// GENERATED by scripts/build-dual-mvu-worldbook-update.mjs --write
(function () {
"use strict";
function createDualWorldbookPlan(book, payload) {
  if (!book?.entries || typeof book.entries !== 'object' || Array.isArray(book.entries)) throw new Error('主世界书不是原始 entries 对象，未修改。');
  const rows = Object.entries(book.entries), seen = new Set();
  for (const [, entry] of rows) {
    if (!Number.isInteger(entry?.uid) || seen.has(entry.uid) || typeof entry.comment !== 'string' || typeof entry.content !== 'string') throw new Error('世界书存在无效或重复 UID／正文，未修改。');
    seen.add(entry.uid);
  }
  function named(name, optional = false) {
    const matches = rows.filter(([, entry]) => entry.comment === name);
    if (matches.length > 1 || !matches.length && !optional) throw new Error('条目「' + name + '」必须唯一，实际为 ' + matches.length + ' 条。');
    return matches[0];
  }
  const header = '<% /* RK_AW_WORLDBOOK_V1 */ %>
';
  const begin = '<% /* RK_AW_ORIGINAL_BEGIN */ %>
', end = '
<% /* RK_AW_ORIGINAL_END */ %>';
  const common = '【同一世界与两座舞台】
两部作品人物共存于同一个世界、互为同行，保留各自的身份、能力、所属与已确认关系；人物资料不等于已登场、与玩家熟识或触发原作事件。本局舞台由 系统.作品 决定，另一侧人物照常存在，不是本局附属 NPC。星辰力与魔力是两套独立体系：不换算数值、不互相供给、不以一方的等级或名次评价另一方。相遇不切换舞台，也不强制进入另一作品剧情。
';
  const world = '<% { const __dualState = getvar('stat_data'); const __dualWorld = (' + payload.worldResolver + ')(__dualState); ';
  function original(content) {
    if (!content.includes('RK_AW_WORLDBOOK_')) {
      if (content.includes(begin) || content.includes(end)) throw new Error('原文含更新器保留标记，未修改。');
      return content;
    }
    if (!content.startsWith(header) || content.split(begin).length !== 2 || content.split(end).length !== 2) throw new Error('已有双作品包装无法识别，请保留备份并人工检查。');
    const first = content.indexOf(begin) + begin.length, last = content.indexOf(end);
    if (last < first) throw new Error('原文边界损坏，未修改。');
    return content.slice(first, last);
  }
  function wrap(content, template, lore = false) {
    const source = original(content);
    if (lore) return header + common + world + "if (__dualWorld !== 'rakudai') { %>
" +
      '【以下资料的适用范围】以下原文仅描述落第来源人物、伐刀者机制及其原作社会背景。保留这些人物在同一世界自然出现的可能。这些制度、先天魔力限制、伐刀分类与赛事默认只适用于落第舞台，不默认套给学战玩家与学战学园；学战人物觉醒为伐刀者后按本局已确认事实适用，不改写其原有体系。资料本身不启动落第剧情线。
<% } %>
' +
      begin + source + end + '
<% } %>';
    return header + common + world + "if (__dualWorld === 'rakudai') { %>
" + begin + source + end +
      '
<% } else { %>
' + template + '
<% } } %>';
  }
  const targets = [
    [named('[MVU]变量列表'), payload.templates.list],
    [named('[MVU]变量更新规则'), payload.templates.update],
  ];
  // The editor's old/new labels are both supported; never choose by numeric UID.
  const formats = ['[MVU]变量输出格式', '[MVU]变量更新格式'].map(name => named(name, true)).filter(Boolean);
  const activeFormats = formats.filter(([, entry]) => entry.disable !== true);
  const format = formats.length === 1 ? formats[0] : activeFormats.length === 1 ? activeFormats[0] : null;
  if (!format) throw new Error('变量输出格式新旧名称无法唯一定位，请只保留一个启用版本。');
  targets.push([format, payload.templates.format]);
  const changes = [];
  function add(row, content) {
    const [key, entry] = row;
    if (content !== entry.content) changes.push({ key, uid: entry.uid, comment: entry.comment, before: structuredClone(entry), content });
  }
  for (const [row, template] of targets) add(row, wrap(row[1].content, template));
  add(named('[initvar]变量初始化'), payload.templates.init);
  const skipped = [];
  for (const name of ['世界设定', '魔力', '能力与招式', '伐刀者', '觉醒', '魔人', '能力系别']) {
    const row = named(name, true);
    if (row) add(row, wrap(row[1].content, '', true)); else skipped.push(name);
  }
  return { changes, skipped };
}
function installDualMvuWorldbookUpdater(W, payload) {
  const slot = '__RK_AW_WORLDBOOK_UPDATER_V1__';
  W[slot]?.destroy();
  const host = W.parent, context = host?.SillyTavern?.getContext;
  if (typeof context !== 'function') throw new Error('需要酒馆助手脚本 iframe 与 SillyTavern 宿主。');
  const api = () => host.SillyTavern.getContext();
  for (const method of ['getCharWorldbookNames', 'getButtonEvent', 'eventOn']) if (typeof W[method] !== 'function') throw new Error('酒馆助手缺少 ' + method);
  for (const method of ['getRequestHeaders', 'saveWorldInfo', 'reloadWorldInfoEditor']) if (typeof api()[method] !== 'function') throw new Error('SillyTavern 缺少 ' + method);
  if (typeof host.fetch !== 'function') throw new Error('宿主不提供同源读取。');
  let pending = null, busy = false, disposed = false;
  const subscriptions = [];
  const sorted = value => Array.isArray(value) ? value.map(sorted) : value && typeof value === 'object' ?
    Object.fromEntries(Object.keys(value).sort().map(key => [key, sorted(value[key])])) : value;
  const canonical = value => JSON.stringify(sorted(value));
  const primary = () => {
    const binding = W.getCharWorldbookNames('current');
    if (typeof binding?.primary !== 'string' || !binding.primary.trim()) throw new Error('当前角色没有绑定主世界书。');
    return binding.primary;
  };
  const owner = () => { const current = api(); return { characterId: current.characterId, groupId: current.groupId, chatId: current.chatId, chat: current.chat }; };
  const owned = (name, savedOwner) => {
    const current = owner();
    if (disposed || primary() !== name || Object.keys(savedOwner).some(key => savedOwner[key] !== current[key])) throw new Error('当前聊天或角色主世界书已变化，请重新预览。');
  };
  async function rawRead(name) {
    const response = await host.fetch('/api/worldinfo/get', { method: 'POST', headers: api().getRequestHeaders(),
      body: JSON.stringify({ name }), cache: 'no-store' });
    if (!response.ok) throw new Error('世界书读取失败：HTTP ' + response.status);
    return response.json();
  }
  function download(name, value) {
    const url = W.URL.createObjectURL(new W.Blob([JSON.stringify(value, null, 2)], { type: 'application/json;charset=utf-8' }));
    const anchor = W.document.createElement('a'); anchor.href = url; anchor.download = name;
    W.document.body.append(anchor); anchor.click(); anchor.remove();
    W.setTimeout(() => W.URL.revokeObjectURL(url), 30000);
  }
  async function preview() {
    pending = null;
    const name = primary(), savedOwner = owner(), book = await rawRead(name); owned(name, savedOwner);
    const plan = createDualWorldbookPlan(book, payload);
    download(name.replace(/[<>:"/\|?*]/g, '_') + '-双作品更新前完整备份.json', book);
    pending = { name, plan, savedOwner };
    W.alert('已准备「' + name + '」：' + plan.changes.length + ' 条正文差异。
' +
      plan.changes.map(change => change.comment + '（UID ' + change.uid + '）').join('
') +
      '
请保留下载的完整原世界书备份。初始化只影响以后新建档案；当前聊天楼层不会修改。
确认后点击「应用双作品世界书更新」。' +
      (plan.skipped.length ? '
本书未找到的可选机制条目：' + plan.skipped.join('、') : ''));
    return plan;
  }
  async function apply() {
    if (!pending) throw new Error('请先点击「预览差异并下载备份」。');
    const { name, plan, savedOwner } = pending; owned(name, savedOwner);
    if (!plan.changes.length) { W.alert('当前正文已是本版，无需写入。'); return; }
    const current = await rawRead(name); owned(name, savedOwner);
    // Re-resolve comments as well as UIDs immediately before writing; duplicates added after preview also fail.
    createDualWorldbookPlan(current, payload);
    for (const change of plan.changes) if (canonical(current.entries?.[change.key]) !== canonical(change.before)) throw new Error('条目「' + change.comment + '」在预览后被修改，请重新预览并备份。');
    const next = structuredClone(current);
    for (const change of plan.changes) next.entries[change.key].content = change.content;
    owned(name, savedOwner);
    await api().saveWorldInfo(name, next, true);
    const saved = await rawRead(name);
    if (canonical(saved) !== canonical(next)) throw new Error('服务器回读与提交内容不一致，不能确认更新成功；请保留备份并检查世界书。');
    pending = null;
    await api().reloadWorldInfoEditor(name);
    W.alert('已核对服务器保存：「' + name + '」的 ' + plan.changes.length + ' 条正文已更新；其他条目与设置保持原值。当前聊天变量没有改动。');
  }
  async function run(action) {
    if (busy || disposed) return;
    busy = true;
    try { return await action(); }
    catch (error) { W.alert('双作品世界书更新未完成：' + (error?.message || String(error))); }
    finally { busy = false; }
  }
  for (const [name, action] of [[payload.buttons[0], preview], [payload.buttons[1], apply]]) subscriptions.push(W.eventOn(W.getButtonEvent(name), () => run(action)));
  const destroy = () => { disposed = true; pending = null; subscriptions.forEach(subscription => subscription.stop()); W.removeEventListener('pagehide', destroy); if (W[slot] === marker) delete W[slot]; };
  const marker = { destroy }; W[slot] = marker; W.addEventListener('pagehide', destroy, { once: true });
  return marker;
}
installDualMvuWorldbookUpdater(window, {"version":"20261104.1","templates":{"list":"<status_current_variable>
<%
// 只裁剪发给模型的副本；当前楼层的事件与结算历史原样保存。
const rkCurrent = getvar('stat_data');
const rkPromptState = rkCurrent && typeof rkCurrent === 'object' ? JSON.parse(JSON.stringify(rkCurrent)) : null;
const rkObject = value => value !== null && typeof value === 'object' && !Array.isArray(value);
if (rkPromptState) {
  delete rkPromptState.$internal;
  // 收据、事件及赛期外赛事数据只从提示副本省略。
  if (rkObject(rkPromptState.系统)) delete rkPromptState.系统.关系计分;
  if (rkObject(rkPromptState.场景)) {
    // 只保留最近 4 条已发生事件，更早的留在存档；不新增字段，避免模型误写。
    const events = rkPromptState.场景.已发生事件;
    if (rkObject(events)) {
      const keys = Object.keys(events), keep = keys.slice(-4), shown = {};
      for (const key of keep) shown[key] = events[key];
      if (keep.length) rkPromptState.场景.已发生事件 = shown;
      else delete rkPromptState.场景.已发生事件;
    }
  }
  if (rkObject(rkPromptState.玩家) && rkObject(rkPromptState.玩家.成长)) {
    const growth = rkPromptState.玩家.成长;
    rkPromptState.玩家.成长 = Object.hasOwn(growth, '经验') ? { 经验: growth.经验 } : {};
  }
}
%>
<%- JSON.stringify(rkPromptState) %>
</status_current_variable>
历史、收据及赛期外赛事账本留在存档，省略不代表未发生；已发生事件只列最近 4 条，更早的凭存档与正文召回，不改写旧条目；保留原记录，按本轮事实提交变化。
","update":"【变量更新规则】
<% const updateSystem = getvar('stat_data.系统') || {}; const updateWorld = Object.prototype.hasOwnProperty.call(updateSystem, '作品') ? updateSystem.作品 : (updateSystem.结构版本 === 4 && updateSystem.开局状态 === '已建档' ? 'rakudai' : null); if (updateSystem.开局状态 !== '已建档' || !['rakudai','asterisk'].includes(updateWorld)) { %>
本局尚未确认有效作品与人物档案。由开局页完成建档，本轮 JSONPatch 为 []，不要自行初始化、推章或套用任一作品的能力规则。
<% } else { %>
本局舞台为 <%= updateWorld === 'asterisk' ? '学战都市（六花）' : '落第骑士' %>。两部作品人物共存于同一个世界、互为同行，各自保留身份、能力与所属机构，不是对方的附属 NPC；按本局地点和已知关系自然互动，人物资料可参考但不等于已登场、与玩家熟识或触发原作事件，未知秘密不写入玩家已知资料。
星辰力与魔力是两套独立体系：不换算数值、不互相供给、不以一方的等级或名次评价另一方；跨体系交手只描述可见结果，不写成能量转换。相遇不切换舞台，不强制触发另一方作品的主线事件。
先读本分支旧值，再核对本轮事实，提交最终值。本局剧情、玩家设定与已保存变量优先于原著默认走向和模型记忆；不强制还原胜负、关系、死亡、觉醒时间或能力。不代玩家决定行动、内心、台词；计划和预告不记成已完成。
主副 API 共用业务字段权限。主回复每轮自行检查场景、成长、遇见或互动人物的好感与支援、联系资料及赛事事实；实际变化当轮提交，不等副 API 或玩家提醒。不因没有重大事件、没有自身成长而略过日常人际变化。补漏与重试均使用当前聊天、楼层和回复页，只补漏或纠错，同一成果、重试和副校正不再次相加。

【保存与字段】
已建档不重建；待建档补丁为 []，由开局页完成建档。v2/v3 先经终端迁移；一辉模式不另建同名 NPC。固定字段及数据类型见输出格式。
字段所有权以输出格式为准：代码维护 /系统、性别、综合初评、成长版本与收据、名册隐藏、恋爱阶段及框架元数据。旧成长申请与收据只读留档；模型更新业务事实，不覆盖父对象重置它们。/系统/已删除人物 随分支保存，不从旧正文重建其中人物。
玩家资料、能力、六维、正式登记等级、成长经验最终值、人际资料及分数均可按已确认事实修正；不另需终端审批。通常写具体叶字段；合并已有对象时保留未提到的资料。能力、事件、人际中的错误条目可以删除，离场或暂时失效不等于删除。

<% if (updateWorld === 'rakudai') { %>
【能力、评级与觉醒】
伐刀能力包含能力系别、能力本质、共通限制、招式；剑术、体术、分析、生活技艺归其他能力。按本局实际学习、应用、改良结果更新，描述自由，不凭招式名称或原著未来资料授予掌握。
六维实际档位按事实保存；永久成长与评级纠错可改六维，临时强化、疲劳或受伤写在描述中。正式登记/重评发生时可改登记等级，开局综合初评仍保留历史。无统一 HP/MP/AP/SP，不将原作比例换算成自造消耗数字。
唯一觉醒开关为 /玩家/魔人觉醒（布尔值），缺字段按 false；本局明确觉醒才设 true，误记可按事实纠正。true 后不反复注入觉醒旧事，不以旧成长境界、卷号、字数或能力名替代布尔开关；觉醒本身不赠经验。

【成长终值】
<% if (getvar('stat_data.玩家.魔人觉醒') === true) { %>
魔人觉醒:true。魔力控制、体能、魔力量可按本轮实际成果成长，已有觉醒不再复核。魔力控制与魔力量分别判断，不自动联动。
<% } else { %>
魔人觉醒:false。魔力控制、体能可成长，魔力量不获新成长经验；本轮明确觉醒后，先写 true，再计算其后实际产生的魔力量成长。
<% } %>
经验来自本轮实际练习、应用、改良或突破。身体实际参与练习才有体能成果，纯想象动作不算肉身训练；历史回忆、跳章和翻日历不补造训练。
主副 API 直接提交 /玩家/成长/经验/<目标> 的非负整数终值及 /玩家/六维/<目标> 的最终档位，不新建成长申请。经验只记魔力控制、体能、魔力量三项，彼此独立。已有经验与六维可据已确认事实纠错，包括未觉醒时的魔力量旧值；纠错不冒充新成长，评级未知时不猜起点。
经验是所提交评级的档内进度。门槛：F100、F+100、E150、E+150、D250、D+250、C400、C+400、B600、B+900、A1200、A+1600。达到门槛连续晋级，逐档扣除门槛并保留余量；S为顶档，保留余量。登记等级不随经验自动改变。无约束时模型也须算好晋级、评级与余量后提交终值。该门槛同用于学战出身人物：他们觉醒后按同一刻度评定等级，不另设一套。

<% } else { %>
【学战能力、武装与序列】
使用 /玩家/学战，保留 /玩家/所属 为所属学园名称，学园ID使用固定代码；只有实际转学或已确认纠错才一起更新。不因遇见其他学园人物就转学。
能力身份、能力机制、共通限制、招式分别保存；武术、分析、生活技术归 /玩家/其他能力。技能沿用说明、条件与代价、掌握状态，不把原作未来招式或仅提出的建议记成已掌握。星辰力以 /玩家/学战/星辰力/说明 记录实际控制、运用与负担，不编造统一数值、HP/MP或经验等级。
武装保存类别、名称、使用条件；自身异能与武装功能分别描述。纯星煌式武装的资格、适合情况和代价以已确认事实为准，未知不补造百分比。获得、失去、改造或条件变化才改武装；没有武装不能凭空授予。
校内序列只表示所属学园排名：已上榜填1至72整数，未知或未上榜的名次为null。前12名属于始页十二人。只按已发生的正式结果或确认纠错改排名，不按战力猜名次、不为设定的名次倒补战绩。
成长按实际学习、练习、改良或突破更新文字与技能掌握状态。/玩家 默认不建伐刀能力、固有灵装、六维、登记等级、综合初评、魔人觉醒或落第成长经验；本局明确觉醒为伐刀者时，按输出格式补 /玩家/登记等级 与 /玩家/伐刀能力，六维与成长经验仍不开。跨体系能力只有玩家明确确认才记在能力机制、本局映射或其他能力中，不自动获得。
<% } %>

【剧情、事件与日程】
<% if (updateWorld === 'rakudai') { %>
宿舍按钮维护 /场景/宿舍 布尔值，缺项按 false；true 表示终端正在显示宿舍背景。模型不得进入宿舍、自动改地点或覆盖该标记；玩家主动点击离开由代码设 false。
